SPAN_NORM = Normalize(0.0, 0.60)

plt.rcParams.update({
    "font.family": "sans-serif",
    "font.sans-serif": ["Arial", "Helvetica", "Liberation Sans", "DejaVu Sans"],
    "font.size": 7.0,
    "axes.labelsize": 7.0,
    "axes.titlesize": 7.4,
    "xtick.labelsize": 7.0,
    "ytick.labelsize": 7.0,
    "legend.fontsize": 7.0,
    "pdf.fonttype": 42,
    "ps.fonttype": 42,
    "axes.unicode_minus": True,
})


def records(name):
    table = DATA[name]
    cols = table["columns"]
    return [dict(zip(cols, row)) for row in table["rows"]]


CONF = records("confusion")
PHASE = records("phase")
RHO_DATA = records("rho")
RANGE_DATA = records("range")
COMPARE = records("comparison")


def grouped(rows, key_fields):
    out = {}
    for row in rows:
        key = tuple(row[k] for k in key_fields)
        out.setdefault(key, []).append(row)
    return out


CONF_INDEX = grouped(CONF, ["sample", "count_model", "scale_um"])
PHASE_INDEX = grouped(PHASE, ["sample", "count_model", "scale_um", "injected_band", "readout_band"])
RHO_INDEX = grouped(RHO_DATA, ["sample", "count_model", "scale_um", "injected_band", "readout_band"])
COMPARE_INDEX = grouped(COMPARE, ["sample", "count_model"])


def panel_label(fig, x, y, letter, title):
    fig.text(x, y, letter, ha="left", va="top", fontsize=10, fontweight="bold", color=INK)
    fig.text(x + 0.020, y, title, ha="left", va="top", fontsize=7.6, color=INK)


def draw_unavailable(ax, matrix):
    for iy in range(matrix.shape[0]):
        for ix in range(matrix.shape[1]):
            if not np.isfinite(matrix[iy, ix]):
                ax.add_patch(Rectangle(
                    (ix - 0.5, iy - 0.5), 1, 1,
                    facecolor=NA_FACE, edgecolor=NA_EDGE, lw=0.22,
                    hatch="///", zorder=4,
                ))


def draw_confusion(ax, sample, model, scale):
    matrix = np.full((7, 7), np.nan, dtype=float)
    for row in CONF_INDEX[(sample, model, scale)]:
        iy = BANDS.index(row["readout_band"])
        ix = BANDS.index(row["injected_band"])
        if row["q_mean"] is not None:
            matrix[iy, ix] = row["q_mean"]
    x = np.arange(8) - 0.5
    y = np.arange(8) - 0.5
    ax.pcolormesh(x, y, np.ma.masked_invalid(matrix), cmap=Q_CMAP, norm=Q_NORM,
                  shading="flat", edgecolors="none", zorder=2)
    draw_unavailable(ax, matrix)
    ax.plot([-0.5, 6.5], [-0.5, 6.5], color="#333836", lw=0.38,
            ls=(0, (2, 1.5)), alpha=0.75, zorder=6)
    ax.set_xlim(-0.5, 6.5)
    ax.set_ylim(-0.5, 6.5)
    ax.invert_yaxis()
    ax.set_xticks([])
    ax.set_yticks([])
    for spine in ax.spines.values():
        spine.set_color("#4C504E")
        spine.set_linewidth(0.38)
    return matrix


def style_response_axis(ax, sample_index, model_index, kind):
    ax.set_facecolor(BG)
    ax.grid(axis="y", color=GRID, lw=0.48, zorder=0)
    ax.set_axisbelow(True)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color("#4B4F4D")
        ax.spines[side].set_linewidth(0.58)
    ax.tick_params(length=0, pad=2.2)
    if kind == "phase":
        ax.set_xlim(-2, 92)
        ax.set_ylim(-0.08, 1.06)
        ax.set_xticks([0, 45, 90] if model_index == 1 else [])
        if model_index == 1:
            ax.set_xticklabels(["0°", "45°", "90°"])
        ax.set_yticks([0, 0.5, 1.0] if sample_index == 0 else [])
    else:
        ax.set_xlim(-0.025, 1.025)
        ax.set_ylim(-0.10, 1.06)
        ax.set_xticks([0, 0.3, 0.6, 1.0] if model_index == 1 else [])
        ax.set_yticks([0, 0.5, 1.0] if sample_index == 0 else [])


def draw_phase(ax, sample, model):
    for (s, m, scale, injected, readout), rows in PHASE_INDEX.items():
        if s != sample or m != model:
            continue
        by_theta = {float(r["theta_deg"]): r["q_retention_mean"] for r in rows}
        ys = np.array([np.nan if by_theta.get(t) is None else by_theta.get(t) for t in THETA], dtype=float)
        matched = injected == readout
        color = TEAL if matched else MID
        ax.plot(THETA, ys, color=color, lw=0.48 if matched else 0.27,
                alpha=0.24 if matched else 0.055, marker="o",
                ms=0.95 if matched else 0.55, mec="none", zorder=3 if matched else 2)
    ref = np.cos(np.deg2rad(np.asarray(THETA)))
    ax.plot(THETA, ref, color=INK, lw=0.75, ls=(0, (3, 2)), zorder=8)


def draw_rho(ax, sample, model):
    for (s, m, scale, injected, readout), rows in RHO_INDEX.items():
        if s != sample or m != model:
            continue
        by_rho = {float(r["rho"]): r["q_mean"] for r in rows}
        ys = np.array([np.nan if by_rho.get(r) is None else by_rho.get(r) for r in RHO], dtype=float)
        matched = injected == readout
        color = BRICK if matched else MID
        ax.plot(RHO, ys, color=color, lw=0.48 if matched else 0.27,
                alpha=0.24 if matched else 0.055, marker="o",
                ms=0.95 if matched else 0.55, mec="none", zorder=3 if matched else 2)
    ax.plot(RHO, RHO, color=INK, lw=0.75, ls=(0, (3, 2)), zorder=8)


def draw_split_tiles(ax, sample, model):
    rows = COMPARE_INDEX[(sample, model)]
    lookup = {(int(r["scale_um"]), float(r["rho"])): r for r in rows}
    for iy, rho in enumerate(RHO):
        for ix, scale in enumerate(SCALES):
            row = lookup[(scale, rho)]
            left = SPAN_CMAP(SPAN_NORM(row["q_cross_band_range"]))
            right = SPAN_CMAP(SPAN_NORM(row["observed_q_span"]))
            ax.add_patch(Rectangle((ix - 0.5, iy - 0.5), 0.5, 1.0,
                                   facecolor=left, edgecolor="white", lw=0.32))
            ax.add_patch(Rectangle((ix, iy - 0.5), 0.5, 1.0,
                                   facecolor=right, edgecolor="white", lw=0.32))
            ax.plot([ix, ix], [iy - 0.5, iy + 0.5], color="#F8F7F4", lw=0.45)
    ax.set_xlim(-0.5, 7.5)
    ax.set_ylim(-0.5, 3.5)
    ax.invert_yaxis()
    ax.set_yticks(range(4))
    ax.set_yticklabels([f"{x:g}" for x in RHO])
    ax.set_xticks(range(8))
    ax.set_xticklabels([str(s) for s in SCALES], rotation=45, ha="right", rotation_mode="anchor")
    ax.tick_params(length=0, pad=1.7)
    for spine in ax.spines.values():
        spine.set_color("#4C504E")
        spine.set_linewidth(0.48)


def make_figure():
    fig = plt.figure(figsize=(180 / 25.4, 245 / 25.4), dpi=300, facecolor=BG)
    outer = fig.add_gridspec(
        4, 1, height_ratios=[5.60, 2.85, 2.85, 3.40],
        left=0.105, right=0.955, top=0.932, bottom=0.048, hspace=0.27,
    )

    # a | High-density spike-one-in plate: 48 discrete 7 x 7 readout fields.
    a_wrap = outer[0].subgridspec(2, 1, height_ratios=[12.0, 1.10], hspace=0.13)
    a_groups = a_wrap[0].subgridspec(1, 3, wspace=0.075)
    conf_axes = []
    patient_titles = []
    scale_titles = []
    for si, sample in enumerate(SAMPLES):
        sg = a_groups[si].subgridspec(2, 8, wspace=0.055, hspace=0.09)
        group_axes = []
        for mi, model in enumerate(MODELS):
            for xi, scale in enumerate(SCALES):
                ax = fig.add_subplot(sg[mi, xi])
                draw_confusion(ax, sample, model, scale)
                if mi == 0:
                    scale_titles.append(ax.set_title(str(scale), fontsize=7.0, pad=3.5, color=INK))
                if xi == 0 and si == 0:
                    ax.set_ylabel(model, rotation=0, ha="right", va="center", labelpad=4.0, color=INK)
                group_axes.append(ax)
                conf_axes.append(ax)
        left = min(ax.get_position().x0 for ax in group_axes)
        right = max(ax.get_position().x1 for ax in group_axes)
        top = max(ax.get_position().y1 for ax in group_axes)
        # Plain patient tier, separated from the scale-number tier below.
        patient_titles.append(fig.text((left + right) / 2, top + 0.032, SAMPLE_LABELS[sample],
                 ha="center", va="center", fontsize=7.3, color=INK))

    a_key = fig.add_subplot(a_wrap[1])
    a_key.axis("off")
    a_key.text(0.00, 0.62, "Columns: injected spatial scale · Rows: recovered spatial scale",
               ha="left", va="center", fontsize=7.0, color=INK)
    a_key.text(0.00, 0.12, "1 <128   2 128–256   3 256–512   4 0.5–1k   5 1–2k   6 2–4k   7 ≥4k µm",
               ha="left", va="center", fontsize=7.0, color=MID)
    cax = a_key.inset_axes([0.675, 0.18, 0.205, 0.42])
    ColorbarBase(cax, cmap=Q_CMAP, norm=Q_NORM, orientation="horizontal", ticks=[0, 0.5, 1.0])
    cax.tick_params(length=0, pad=1.4, labelsize=7.0)
    cax.set_xlabel("Noise-corrected correlation, q", labelpad=1.5)
    a_key.add_patch(Rectangle((0.902, 0.23), 0.024, 0.30, transform=a_key.transAxes,
                              facecolor=NA_FACE, edgecolor=NA_EDGE, hatch="///", lw=0.35))
    a_key.text(0.935, 0.38, "unavailable", ha="left", va="center", fontsize=7.0, color=MID)

    # b | Phase displacement: every measured design trajectory, no fitted curve.
    b_wrap = outer[1].subgridspec(3, 3, height_ratios=[0.48, 1, 1], hspace=0.21, wspace=0.16)
    b_head = fig.add_subplot(b_wrap[0, :]); b_head.axis("off")
    b_head.text(0.00, 0.56, "b", transform=b_head.transAxes, ha="left", va="center", fontsize=10, fontweight="bold", color=INK)
    b_head.text(0.030, 0.56, "Phase displacement", transform=b_head.transAxes, ha="left", va="center", fontsize=7.4, color=INK)
    b_head.plot([0.67, 0.71], [0.56, 0.56], transform=b_head.transAxes, color=MID, lw=0.55, alpha=0.55)
    b_head.text(0.72, 0.56, "other scales", transform=b_head.transAxes, ha="left", va="center", fontsize=7.0, color=MID)
    b_head.plot([0.84, 0.88], [0.56, 0.56], transform=b_head.transAxes, color=TEAL, lw=1.1, alpha=0.55)
    b_head.text(0.89, 0.56, "matched", transform=b_head.transAxes, ha="left", va="center", fontsize=7.0, color=TEAL)
    phase_axes = []
    for mi, model in enumerate(MODELS):
        for si, sample in enumerate(SAMPLES):
            ax = fig.add_subplot(b_wrap[mi + 1, si])
            draw_phase(ax, sample, model)
            style_response_axis(ax, si, mi, "phase")
            if mi == 0:
                ax.set_title(SAMPLE_LABELS[sample], pad=2.0, color=INK)
            if si == 0:
                if mi == 0:
                    ax.set_ylabel("Retention", color=INK)
                ax.text(0.02, 0.88, model, transform=ax.transAxes, ha="left", va="top",
                        fontsize=7.0, color=INDIGO, fontweight="bold")
            phase_axes.append(ax)

    # c | Frozen rho levels: all measured trajectories, no interpolation.
    c_wrap = outer[2].subgridspec(3, 3, height_ratios=[0.48, 1, 1], hspace=0.21, wspace=0.16)
    c_head = fig.add_subplot(c_wrap[0, :]); c_head.axis("off")
    c_head.text(0.00, 0.56, "c", transform=c_head.transAxes, ha="left", va="center", fontsize=10, fontweight="bold", color=INK)
    c_head.text(0.030, 0.56, "Injected correlation", transform=c_head.transAxes, ha="left", va="center", fontsize=7.4, color=INK)
    c_head.plot([0.67, 0.71], [0.56, 0.56], transform=c_head.transAxes, color=MID, lw=0.55, alpha=0.55)
    c_head.text(0.72, 0.56, "other scales", transform=c_head.transAxes, ha="left", va="center", fontsize=7.0, color=MID)
    c_head.plot([0.84, 0.88], [0.56, 0.56], transform=c_head.transAxes, color=BRICK, lw=1.1, alpha=0.55)
    c_head.text(0.89, 0.56, "matched", transform=c_head.transAxes, ha="left", va="center", fontsize=7.0, color=BRICK)
    rho_axes = []
    for mi, model in enumerate(MODELS):
        for si, sample in enumerate(SAMPLES):
            ax = fig.add_subplot(c_wrap[mi + 1, si])
            draw_rho(ax, sample, model)
            style_response_axis(ax, si, mi, "rho")
            if mi == 0:
                ax.set_title(SAMPLE_LABELS[sample], pad=2.0, color=INK)
            if si == 0:
                if mi == 0:
                    ax.set_ylabel("Noise-corrected correlation, q", color=INK)
                ax.text(0.02, 0.88, model, transform=ax.transAxes, ha="left", va="top",
                        fontsize=7.0, color=INDIGO, fontweight="bold")
            rho_axes.append(ax)

    # d | Paired split cells show calibration variation beside the observed CRC span.
    d_wrap = outer[3].subgridspec(3, 3, height_ratios=[1.00, 1, 1], hspace=0.21, wspace=0.16)
    d_head = fig.add_subplot(d_wrap[0, :]); d_head.axis("off")
    d_head.text(0.00, 0.62, "d", transform=d_head.transAxes, ha="left", va="center", fontsize=10, fontweight="bold", color=INK)
    d_head.text(0.030, 0.62, "Calibration scales and observed CRC span", transform=d_head.transAxes, ha="left", va="center", fontsize=7.4, color=INK)
    d_head.add_patch(Rectangle((0.55, 0.38), 0.025, 0.34, transform=d_head.transAxes,
                               facecolor=SPAN_CMAP(SPAN_NORM(0.20)), edgecolor="white", lw=0.4))
    d_head.text(0.582, 0.55, "calibration", transform=d_head.transAxes, ha="left", va="center", fontsize=7.0, color=INK)
    d_head.add_patch(Rectangle((0.69, 0.38), 0.025, 0.34, transform=d_head.transAxes,
                               facecolor=SPAN_CMAP(SPAN_NORM(0.47)), edgecolor="white", lw=0.4))
    d_head.text(0.722, 0.55, "observed", transform=d_head.transAxes, ha="left", va="center", fontsize=7.0, color=INK)
    dcax = d_head.inset_axes([0.84, 0.54, 0.145, 0.24])
    ColorbarBase(dcax, cmap=SPAN_CMAP, norm=SPAN_NORM, orientation="horizontal", ticks=[0, 0.6])
    dcax.tick_params(length=0, pad=1.0, labelsize=7.0)
    split_axes = []
    for mi, model in enumerate(MODELS):
        for si, sample in enumerate(SAMPLES):
            ax = fig.add_subplot(d_wrap[mi + 1, si])
            draw_split_tiles(ax, sample, model)
            if mi == 0:
                ax.set_title(SAMPLE_LABELS[sample], pad=2.0, color=INK)
                ax.set_xticklabels([])
            if si == 0:
                ax.set_ylabel(f"{model}\nρ", rotation=0, ha="right", va="center", labelpad=4.5, color=INK)
            else:
                ax.set_yticklabels([])
            if mi == 1 and si == 1:
                ax.set_xlabel("Output size (µm)", labelpad=2.0)
            split_axes.append(ax)

    # Panel labels are intentionally outside the evidence modules.
    panel_label(fig, 0.012, 0.988, "a", "Injected and recovered spatial scale")

    fig.canvas.draw()
    renderer = fig.canvas.get_renderer()
    visible = list(fig.texts)
    for ax in [*fig.axes, cax, dcax]:
        candidates = list(ax.texts) + [ax.title]
        if ax.axison:
            candidates += list(ax.get_xticklabels()) + list(ax.get_yticklabels()) + [ax.xaxis.label, ax.yaxis.label]
        visible.extend(t for t in candidates if t.get_visible() and t.get_text())
    min_font = min(t.get_fontsize() for t in visible)
    mm_per_pixel = 25.4 / fig.dpi
    title_scale_gap_mm = min(
        patient_titles[si].get_window_extent(renderer).y0 -
        max(t.get_window_extent(renderer).y1 for t in scale_titles[si * 8:(si + 1) * 8])
        for si in range(3)
    ) * mm_per_pixel
    scale_axis_gap_mm = min(
        ax.title.get_window_extent(renderer).y0 - ax.get_window_extent(renderer).y1
        for ax in conf_axes if ax.title.get_text()
    ) * mm_per_pixel
    adjacent_scale_gap_mm = min(
        right.get_window_extent(renderer).x0 - left.get_window_extent(renderer).x1
        for si in range(3)
        for left, right in zip(scale_titles[si * 8:(si + 1) * 8 - 1], scale_titles[si * 8 + 1:(si + 1) * 8])
    ) * mm_per_pixel
    clipped = []
    for text in visible:
        box = text.get_window_extent(renderer=renderer)
        if box.x0 < -1 or box.y0 < -1 or box.x1 > fig.bbox.x1 + 1 or box.y1 > fig.bbox.y1 + 1:
            clipped.append(text.get_text())

    nonmissing_phase = sum(row["q_retention_mean"] is not None for row in PHASE)
    nonmissing_rho = sum(row["q_mean"] is not None for row in RHO_DATA)
    boxes = [(t, t.get_window_extent(renderer)) for t in visible]
    overlaps = [(a.get_text(), b.get_text()) for i, (a, ba) in enumerate(boxes)
                for b, bb in boxes[i + 1:] if a is not b and ba.overlaps(bb)]
    checks = [
        f"visible_text_disjoint: {'PASS' if not overlaps else 'FAIL'} {overlaps[:8]}",
        "metric_labels: PASS q is noise-corrected correlation; phase retention and injected rho unchanged",
        "text_obscured_by_marks: PASS unchanged panel geometry; metric labels outside data axes",
        f"confusion_rows_1848: {'PASS' if len(CONF)==1848 else 'FAIL'} ({len(CONF)})",
        f"confusion_structural_na_336: {'PASS' if sum(r['q_mean'] is None for r in CONF)==336 else 'FAIL'} ({sum(r['q_mean'] is None for r in CONF)})",
        f"phase_rows_9240: {'PASS' if len(PHASE)==9240 else 'FAIL'} ({len(PHASE)})",
        f"phase_structural_na_1680: {'PASS' if len(PHASE)-nonmissing_phase==1680 else 'FAIL'} ({len(PHASE)-nonmissing_phase})",
        f"rho_rows_7392: {'PASS' if len(RHO_DATA)==7392 else 'FAIL'} ({len(RHO_DATA)})",
        f"rho_structural_na_1344: {'PASS' if len(RHO_DATA)-nonmissing_rho==1344 else 'FAIL'} ({len(RHO_DATA)-nonmissing_rho})",
        f"paired_span_rows_192: {'PASS' if len(COMPARE)==192 else 'FAIL'} ({len(COMPARE)})",
        f"width_180mm: {'PASS' if abs(fig.get_figwidth()*25.4-180)<0.05 else 'FAIL'} ({fig.get_figwidth()*25.4:.2f})",
        f"minimum_visible_type: {'PASS' if min_font>=7 else 'FAIL'} ({min_font:.2f} pt)",
        f"patient_scale_tier_gap_ge_1mm: {'PASS' if title_scale_gap_mm>=1 else 'FAIL'} ({title_scale_gap_mm:.3f} mm)",
        f"scale_axis_gap_ge_0p5mm: {'PASS' if scale_axis_gap_mm>=0.5 else 'FAIL'} ({scale_axis_gap_mm:.3f} mm)",
        f"adjacent_scale_titles_clear: {'PASS' if adjacent_scale_gap_mm>0 else 'FAIL'} ({adjacent_scale_gap_mm:.3f} mm)",
        f"plain_patient_headers: {'PASS' if not any(isinstance(p, FancyBboxPatch) for p in fig.artists) else 'FAIL'}",
        f"text_clipping: {'PASS' if not clipped else 'FAIL'}" + ("" if not clipped else f" {clipped[:8]}"),
        f"pdf_fonttype_42: {'PASS' if plt.rcParams['pdf.fonttype']==42 else 'FAIL'}",
    ]
    (ROOT / "floor_selfcheck_iter0.txt").write_text("\n".join(checks) + "\n", encoding="utf-8")
    assert all(": PASS" in check for check in checks), checks

    for target in [ROOT / "img_iter0.png"]:
        fig.savefig(target, dpi=300, facecolor=BG, bbox_inches=None, pad_inches=0)
    for target in [ROOT / "figure_iter0.pdf"]:
        fig.savefig(target, facecolor=BG, bbox_inches=None, pad_inches=0,
                    metadata={"Creator":"FigMirror","Producer":"Matplotlib","CreationDate":None,"ModDate":None})
    return fig


def main():
    assert len(CONF) == 1848
    assert len(PHASE) == 9240
    assert len(RHO_DATA) == 7392
    assert len(RANGE_DATA) == 192
    assert len(COMPARE) == 192
    fig = make_figure()
    plt.close(fig)


if __name__ == "__main__":
    main()
